('segment_values_clear_default_for_wipe','[]'::jsonb),
('stored_value_entries_immutable','["search_path=public,pg_catalog"]'::jsonb),
('subscription_amendment_immutable_guard','[]'::jsonb),
('subscription_period_invoice_immutable_guard','[]'::jsonb),
('subscription_plan_version_immutable_guard','[]'::jsonb),
('subscription_version_component_immutable_guard','[]'::jsonb),
('subsidiary_tree_guard','[]'::jsonb),
('tax_filing_immutable_guard','[]'::jsonb),
('trg_application_open_balance','[]'::jsonb),
('trg_journal_line_open_balance','[]'::jsonb),
('usage_prepaid_draws_append_only_guard','[]'::jsonb),
('usage_rating_bands_draft_only_guard','[]'::jsonb),
('usage_rating_published_immutable_guard','[]'::jsonb),
('warehouse_execution_history_guard','["search_path=public,pg_catalog"]'::jsonb),
('warehouse_execution_task_guard','["search_path=public,pg_catalog"]'::jsonb),
('wip_prebill_event_append_only_guard','[]'::jsonb),
('withholding_deductions_guard','["search_path=public,pg_catalog"]'::jsonb),
('withholding_returns_guard','["search_path=public,pg_catalog"]'::jsonb),
('worker_employment_versions_closure_guard','[]'::jsonb)
), problems AS (
 SELECT 'guard_body_changed' AS problem,p.proname AS subject,k.source AS detail
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN known_functions k ON k.name=p.proname
 WHERE n.nspname='public' AND (encode(public.digest(p.prosrc,'sha256'),'hex') NOT IN(k.old_digest,k.new_digest) OR p.prorettype<>'trigger'::regtype OR p.pronargs<>0)
 UNION ALL
 SELECT 'guard_attributes_changed',p.proname,'Expected published invoker, volatile PL/pgSQL trigger attributes and search path'
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN known_attributes k ON k.name=p.proname
 JOIN pg_language l ON l.oid=p.prolang
 WHERE n.nspname='public' AND (p.prosecdef OR p.provolatile<>'v' OR p.proisstrict OR p.proleakproof OR p.proparallel<>'u' OR l.lanname<>'plpgsql'
   OR coalesce((SELECT jsonb_agg(regexp_replace(value,'\s','','g') ORDER BY value) FROM unnest(p.proconfig) value),'[]'::jsonb)<>k.config)
 UNION ALL
 SELECT 'unknown_delete_trigger',c.relname||'.'||t.tgname,p.proname
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid
 WHERE n.nspname='public' AND NOT t.tgisinternal AND (t.tgtype::integer & 8)<>0
 AND NOT (t.tgname IN ('tenant_retirement_fence','tenant_retirement_org_fence') AND p.proname='openbooks_tenant_retirement_fence')
 AND NOT EXISTS(SELECT 1 FROM known_triggers k WHERE k.table_name=c.relname AND k.trigger_name=t.tgname AND k.function_name=p.proname AND p.pronamespace='public'::regnamespace)
 UNION ALL
 SELECT 'disabled_delete_trigger',c.relname||'.'||t.tgname,t.tgenabled::text
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND NOT t.tgisinternal AND (t.tgtype::integer & 8)<>0 AND t.tgenabled NOT IN ('O','A')
)
SELECT '0626.'||problem AS code,'refuse' AS severity,subject,detail,
 'Preserve the live schema; qualify the exact published guard contract before tenant retirement. Never disable a guard.' AS remedy
FROM problems ORDER BY code,subject

 LOOP RAISE EXCEPTION 'Tenant retirement preflight refused: % % (%)',refusal.code,refusal.subject,refusal.detail; END LOOP;
END $admission$;

-- Recoverable tenant retirement. Authority survives the retired organization and
-- admits DELETE only in one trusted maintenance transaction. Normal financial
-- updates retain every existing guard.
SET lock_timeout = '5s';
CREATE SCHEMA tenant_retirement;
REVOKE ALL ON SCHEMA tenant_retirement FROM PUBLIC;
GRANT USAGE ON SCHEMA tenant_retirement TO PUBLIC;

CREATE TABLE tenant_retirement.runs (
 id uuid PRIMARY KEY,
 plan_digest text NOT NULL CHECK (plan_digest ~ '^[0-9a-f]{64}$'),
 catalog_digest text NOT NULL,
 database_identity jsonb NOT NULL,
 retain_ids uuid[] NOT NULL,
 target_ids uuid[] NOT NULL,
 actor_id uuid NOT NULL,
 reason text NOT NULL CHECK (length(reason) BETWEEN 12 AND 2000),
 recovery_evidence jsonb NOT NULL,
 reviewed_state jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK (cardinality(retain_ids)>0 AND cardinality(target_ids)>0 AND NOT retain_ids && target_ids)
);
CREATE TABLE tenant_retirement.fences (
 tenant_id uuid PRIMARY KEY,
 run_id uuid REFERENCES tenant_retirement.runs(id),
 state text NOT NULL DEFAULT 'active' CHECK (state IN ('active','quarantined','deleted')),
 receipt jsonb,
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK ((state='active')=(run_id IS NULL))
);
CREATE TABLE tenant_retirement.delete_authorities (
 transaction_id bigint NOT NULL,
 backend_pid integer NOT NULL,
 tenant_id uuid NOT NULL REFERENCES tenant_retirement.fences(tenant_id),
 run_id uuid NOT NULL REFERENCES tenant_retirement.runs(id),
 login_name text NOT NULL,
 PRIMARY KEY(transaction_id)
);
-- These rows are recovery manifests, not an object-storage deletion queue.
CREATE TABLE tenant_retirement.storage_manifests (
 run_id uuid NOT NULL REFERENCES tenant_retirement.runs(id),
 tenant_id uuid NOT NULL,
 manifest jsonb NOT NULL,
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(run_id,tenant_id)
);
CREATE TABLE tenant_retirement.events (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 run_id uuid NOT NULL REFERENCES tenant_retirement.runs(id),
 tenant_id uuid,
 kind text NOT NULL,
 login_name text NOT NULL,
 detail jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
REVOKE ALL ON ALL TABLES IN SCHEMA tenant_retirement FROM PUBLIC;
INSERT INTO tenant_retirement.fences(tenant_id) SELECT id FROM public.orgs;

CREATE FUNCTION tenant_retirement.openbooks_retirement_trusted_login() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT coalesce((SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=session_user),false)
$$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_row_org(p_table text,p_row jsonb) RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE tenant uuid;
BEGIN
 IF p_row ? 'org_id' THEN RETURN (p_row->>'org_id')::uuid; END IF;
 IF p_table='orgs' THEN RETURN (p_row->>'id')::uuid; END IF;
 IF p_table='file_versions' THEN
  SELECT org_id INTO tenant FROM public.files WHERE id=(p_row->>'file_id')::uuid;
 ELSIF p_table='file_blobs' THEN
  SELECT f.org_id INTO tenant FROM public.file_versions v JOIN public.files f ON f.id=v.file_id WHERE v.id=(p_row->>'version_id')::uuid;
 ELSIF p_table='tax_group_members' THEN
  SELECT org_id INTO tenant FROM public.tax_groups WHERE id=(p_row->>'tax_group_id')::uuid;
 ELSIF p_table IN ('auth_login_challenges','auth_login_events','auth_login_state','auth_mfa_factors','auth_oidc_identities','auth_password_resets','auth_sessions') THEN
  SELECT org_id INTO tenant FROM public.users WHERE id=(p_row->>'user_id')::uuid;
 END IF;
 RETURN tenant;
END $$;

CREATE FUNCTION tenant_retirement.openbooks_tenant_retirement_delete_allowed(p_table text,p_row jsonb) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT tenant_retirement.openbooks_retirement_trusted_login() AND EXISTS (
  SELECT 1 FROM tenant_retirement.delete_authorities a
  JOIN tenant_retirement.fences f ON f.tenant_id=a.tenant_id AND f.run_id=a.run_id
  WHERE a.tenant_id=tenant_retirement.openbooks_retirement_row_org(p_table,p_row)
   AND a.transaction_id=txid_current() AND a.backend_pid=pg_backend_pid()
   AND a.login_name=session_user AND f.state IN ('quarantined','deleted'))
$$;

-- A persistent row lock closes the repeatable-read snapshot race: a writer
-- whose old snapshot predates quarantine must serialize or abort, never pass a
-- missing-row or caller-controlled advisory/GUC test.
CREATE FUNCTION tenant_retirement.openbooks_assert_tenant_available(p_tenant uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE status text;
BEGIN
 SELECT state INTO status FROM tenant_retirement.fences WHERE tenant_id=p_tenant FOR SHARE;
 IF status IS DISTINCT FROM 'active' THEN
  RAISE EXCEPTION 'Company % is unavailable for changes because its retirement fence is %',p_tenant,coalesce(status,'missing') USING ERRCODE='55000';
 END IF;
END $$;

CREATE FUNCTION tenant_retirement.openbooks_tenant_retirement_fence() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE old_tenant uuid; new_tenant uuid;
BEGIN
 IF TG_OP='DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN RETURN OLD; END IF;
 IF TG_OP IN ('DELETE','UPDATE') THEN old_tenant:=tenant_retirement.openbooks_retirement_row_org(TG_TABLE_NAME,to_jsonb(OLD)); END IF;
 IF TG_OP IN ('INSERT','UPDATE') THEN new_tenant:=tenant_retirement.openbooks_retirement_row_org(TG_TABLE_NAME,to_jsonb(NEW)); END IF;
 IF old_tenant IS NOT NULL THEN PERFORM tenant_retirement.openbooks_assert_tenant_available(old_tenant); END IF;
 IF new_tenant IS NOT NULL AND new_tenant IS DISTINCT FROM old_tenant THEN PERFORM tenant_retirement.openbooks_assert_tenant_available(new_tenant); END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE FUNCTION tenant_retirement.openbooks_tenant_retirement_new_org() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 INSERT INTO tenant_retirement.fences(tenant_id) VALUES(NEW.id);
 RETURN NEW;
END $$;
CREATE TRIGGER tenant_retirement_new_org AFTER INSERT ON public.orgs FOR EACH ROW EXECUTE FUNCTION tenant_retirement.openbooks_tenant_retirement_new_org();
CREATE TRIGGER tenant_retirement_org_fence BEFORE UPDATE OR DELETE ON public.orgs FOR EACH ROW EXECUTE FUNCTION tenant_retirement.openbooks_tenant_retirement_fence();
DO $$
DECLARE target record;
BEGIN
 FOR target IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind='r' AND (
  EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attname='org_id' AND NOT a.attisdropped)
  OR c.relname IN ('file_versions','file_blobs','tax_group_members','auth_login_challenges','auth_login_events','auth_login_state','auth_mfa_factors','auth_oidc_identities','auth_password_resets','auth_sessions'))
 ORDER BY c.relname LOOP
  EXECUTE format('CREATE TRIGGER tenant_retirement_fence BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION tenant_retirement.openbooks_tenant_retirement_fence()',target.relname);
 END LOOP;
END $$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_catalog_digest() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT encode(public.digest(coalesce(string_agg(evidence,E'\n' ORDER BY evidence),''),'sha256'),'hex') FROM (
 SELECT 'column:'||c.relname||':'||a.attnum||':'||a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull||':'||a.attidentity||':'||a.attgenerated||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),'') AS evidence
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum
 WHERE n.nspname IN ('public','tenant_retirement') AND c.relkind IN ('r','p')
 UNION ALL SELECT 'relation:'||n.nspname||'.'||c.relname||':'||c.relowner::regrole::text||':'||coalesce(c.relacl::text,'')||':'||c.relrowsecurity||':'||c.relforcerowsecurity
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','tenant_retirement') AND c.relkind IN ('r','p')
 UNION ALL SELECT 'index:'||n.nspname||'.'||c.relname||':'||pg_get_indexdef(i.indexrelid)
 FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','tenant_retirement')
 UNION ALL SELECT 'policy:'||c.relname||':'||p.polname||':'||p.polroles::text||':'||p.polcmd||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'')
 FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','tenant_retirement')
 UNION ALL SELECT 'constraint:'||c.relname||':'||k.conname||':'||pg_get_constraintdef(k.oid)
 FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','tenant_retirement')
 UNION ALL SELECT 'trigger:'||c.relname||':'||t.tgname||':'||t.tgenabled||':'||pg_get_triggerdef(t.oid)||':'||pg_get_functiondef(t.tgfoid)
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal
 UNION ALL SELECT 'function:'||p.oid::regprocedure::text||':'||p.proowner::regrole::text||':'||coalesce(p.proacl::text,'')||':'||pg_get_functiondef(p.oid)
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='tenant_retirement'
 UNION ALL SELECT 'migration:'||filename||':'||sha256 FROM public._applied_migrations
 ) catalog
$$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_register(p_id uuid,p_plan text,p_catalog text,p_database jsonb,p_retained uuid[],p_targets uuid[],p_actor uuid,p_reason text,p_recovery jsonb,p_state jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE target uuid; actual uuid[]; expected uuid[]; prior tenant_retirement.runs;
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Tenant retirement requires the dedicated maintenance login' USING ERRCODE='42501'; END IF;
 IF p_database IS DISTINCT FROM jsonb_build_object('database',current_database(),'serverAddress',inet_server_addr()::text,'serverPort',inet_server_port(),'clusterName',current_setting('cluster_name')) THEN RAISE EXCEPTION 'Retirement database identity changed'; END IF;
 IF p_catalog IS DISTINCT FROM tenant_retirement.openbooks_retirement_catalog_digest() THEN RAISE EXCEPTION 'Retirement schema or guard catalog changed'; END IF;
 IF p_plan IS NULL OR p_plan !~ '^[0-9a-f]{64}$' OR p_catalog IS NULL OR p_catalog !~ '^[0-9a-f]{64}$'
  OR coalesce(cardinality(p_retained),0)<1 OR coalesce(cardinality(p_targets),0)<1
  OR length(btrim(coalesce(p_reason,'')))<12 OR length(p_reason)>2000
  OR jsonb_typeof(p_state) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Reviewed identities, partition, reason and content evidence are required'; END IF;
 IF jsonb_typeof(p_recovery) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Recovery evidence must be an object'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(p_recovery))<>6 OR EXISTS(
  SELECT 1 FROM unnest(ARRAY['backupSha256','restoreReceiptSha256','preservationReceiptSha256','objectRetentionReceiptSha256','verifiedAt','verifier']) key
  WHERE jsonb_typeof(p_recovery->key) IS DISTINCT FROM 'string')
  OR p_recovery->>'backupSha256' !~ '^[0-9a-f]{64}$' OR p_recovery->>'restoreReceiptSha256' !~ '^[0-9a-f]{64}$'
  OR p_recovery->>'preservationReceiptSha256' !~ '^[0-9a-f]{64}$' OR p_recovery->>'objectRetentionReceiptSha256' !~ '^[0-9a-f]{64}$'
  OR length(btrim(coalesce(p_recovery->>'verifier','')))<3 THEN RAISE EXCEPTION 'Verified backup, full restore, preservation and object retention attestations are required'; END IF;
 IF (p_recovery->>'verifiedAt')::timestamptz > clock_timestamp() OR (p_recovery->>'verifiedAt')::timestamptz < clock_timestamp()-interval '24 hours' THEN RAISE EXCEPTION 'Recovery evidence must be verified within 24 hours'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND org_id=ANY(p_retained) AND is_active) THEN RAISE EXCEPTION 'Retirement actor must be an active identity in a retained company'; END IF;
 SELECT * INTO prior FROM tenant_retirement.runs WHERE id=p_id;
 IF FOUND THEN
  IF (prior.plan_digest,prior.catalog_digest,prior.database_identity,prior.retain_ids,prior.target_ids,prior.actor_id,prior.reason,prior.recovery_evidence,prior.reviewed_state)
   IS DISTINCT FROM (p_plan,p_catalog,p_database,p_retained,p_targets,p_actor,p_reason,p_recovery,p_state) THEN RAISE EXCEPTION 'Retirement run identity is already bound to different evidence'; END IF;
  RETURN p_id;
 END IF;
 SELECT array_agg(id ORDER BY id) INTO actual FROM public.orgs;
 SELECT array_agg(x ORDER BY x) INTO expected FROM unnest(p_retained||p_targets) x;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Reviewed retain/retire partition does not match live company identities'; END IF;
 INSERT INTO tenant_retirement.runs(id,plan_digest,catalog_digest,database_identity,retain_ids,target_ids,actor_id,reason,recovery_evidence,reviewed_state)
 VALUES(p_id,p_plan,p_catalog,p_database,p_retained,p_targets,p_actor,p_reason,p_recovery,p_state);
 FOR target IN SELECT unnest(p_targets) ORDER BY 1 LOOP
  UPDATE tenant_retirement.fences SET run_id=p_id,state='quarantined',updated_at=clock_timestamp() WHERE tenant_id=target AND state='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'Company % already belongs to another retirement or lacks a fence',target; END IF;
 END LOOP;
 INSERT INTO tenant_retirement.events(run_id,kind,login_name,detail) VALUES(p_id,'admitted',session_user,jsonb_build_object('actorId',p_actor,'planDigest',p_plan));
 RETURN p_id;
END $$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_begin(p_run uuid,p_tenant uuid,p_plan text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE run tenant_retirement.runs; fence tenant_retirement.fences; actual uuid[]; expected uuid[];
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM tenant_retirement.runs WHERE id=p_run;
 IF NOT FOUND OR run.plan_digest IS DISTINCT FROM p_plan OR NOT p_tenant=ANY(run.target_ids) THEN RAISE EXCEPTION 'Unreviewed retirement target or plan'; END IF;
 IF run.catalog_digest IS DISTINCT FROM tenant_retirement.openbooks_retirement_catalog_digest() THEN RAISE EXCEPTION 'Retirement catalog changed; preserve quarantine and review a new native plan'; END IF;
 IF run.database_identity IS DISTINCT FROM jsonb_build_object('database',current_database(),'serverAddress',inet_server_addr()::text,'serverPort',inet_server_port(),'clusterName',current_setting('cluster_name')) THEN RAISE EXCEPTION 'Retirement database identity changed'; END IF;
 SELECT array_agg(id ORDER BY id) INTO actual FROM public.orgs;
 SELECT array_agg(id ORDER BY id) INTO expected FROM (SELECT unnest(run.retain_ids) AS id UNION ALL SELECT tenant_id FROM tenant_retirement.fences WHERE run_id=p_run AND state<>'deleted') remaining;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Retirement company inventory changed'; END IF;
 SELECT * INTO fence FROM tenant_retirement.fences WHERE tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND OR fence.run_id IS DISTINCT FROM p_run THEN RAISE EXCEPTION 'Retirement fence ownership changed'; END IF;
 IF fence.state='deleted' THEN
  IF EXISTS(SELECT 1 FROM public.orgs WHERE id=p_tenant) THEN RAISE EXCEPTION 'Retirement receipt conflicts with surviving company'; END IF;
  RETURN false;
 END IF;
 IF fence.state<>'quarantined' THEN RAISE EXCEPTION 'Retirement target is not quarantined'; END IF;
 INSERT INTO tenant_retirement.delete_authorities(transaction_id,backend_pid,tenant_id,run_id,login_name)
 VALUES(txid_current(),pg_backend_pid(),p_tenant,p_run,session_user);
 RETURN true;
END $$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_storage(p_run uuid,p_tenant uuid,p_manifest jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 IF NOT tenant_retirement.openbooks_tenant_retirement_delete_allowed('orgs',jsonb_build_object('id',p_tenant)) OR NOT EXISTS(SELECT 1 FROM tenant_retirement.fences WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined') THEN RAISE EXCEPTION 'Current retirement authority required'; END IF;
 INSERT INTO tenant_retirement.storage_manifests(run_id,tenant_id,manifest) VALUES(p_run,p_tenant,p_manifest);
END $$;
CREATE FUNCTION tenant_retirement.openbooks_retirement_finish(p_run uuid,p_tenant uuid,p_receipt jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE relation record; remains boolean;
BEGIN
 IF NOT tenant_retirement.openbooks_tenant_retirement_delete_allowed('orgs',jsonb_build_object('id',p_tenant)) OR NOT EXISTS(SELECT 1 FROM tenant_retirement.fences WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined') THEN RAISE EXCEPTION 'Current retirement authority required'; END IF;
 IF EXISTS(SELECT 1 FROM public.orgs WHERE id=p_tenant) THEN RAISE EXCEPTION 'Company still exists; retirement cannot be certified'; END IF;
 IF NOT EXISTS(SELECT 1 FROM tenant_retirement.storage_manifests WHERE run_id=p_run AND tenant_id=p_tenant) THEN RAISE EXCEPTION 'Storage recovery manifest missing'; END IF;
 FOR relation IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attname='org_id' AND NOT a.attisdropped) LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE org_id=$1)',relation.relname) INTO remains USING p_tenant;
  IF remains THEN RAISE EXCEPTION 'Retirement left tenant rows in %',relation.relname; END IF;
 END LOOP;
 UPDATE tenant_retirement.fences SET state='deleted',receipt=p_receipt,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined';
 IF NOT FOUND THEN RAISE EXCEPTION 'Retirement completion did not update its owned fence'; END IF;
 INSERT INTO tenant_retirement.events(run_id,tenant_id,kind,login_name,detail) VALUES(p_run,p_tenant,'deleted',session_user,p_receipt);
END $$;


