 ) AS expected(name,old_digest,new_digest,source,patch) WHERE patch LOOP
  SELECT p.oid,p.prosrc INTO proc FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=contract.name AND p.pronargs=0;
  IF NOT FOUND THEN CONTINUE; END IF;
  IF encode(public.digest(proc.prosrc,'sha256'),'hex')=contract.new_digest THEN CONTINUE; END IF;
  IF encode(public.digest(proc.prosrc,'sha256'),'hex')<>contract.old_digest THEN RAISE EXCEPTION 'Guard changed during migration: %',contract.name; END IF;
  replacement:=regexp_replace(proc.prosrc,'\m[Bb][Ee][Gg][Ii][Nn]\M',E'BEGIN\n  IF TG_OP = ''DELETE'' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN\n    RETURN OLD;\n  END IF;\n');
  IF encode(public.digest(replacement,'sha256'),'hex')<>contract.new_digest THEN
   -- Preserve the original BEGIN spelling; the reviewed digest includes it.
   replacement:=regexp_replace(proc.prosrc,'(\m[Bb][Ee][Gg][Ii][Nn]\M)',E'\\1\n  IF TG_OP = ''DELETE'' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN\n    RETURN OLD;\n  END IF;\n');
  END IF;
  IF encode(public.digest(replacement,'sha256'),'hex')<>contract.new_digest THEN RAISE EXCEPTION 'Guard replacement differs from published body: %',contract.name; END IF;
  definition:=replace(pg_get_functiondef(proc.oid),proc.prosrc,replacement);
  EXECUTE definition;
 END LOOP;
END $guards$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_status(p_run uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE result jsonb;
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 SELECT jsonb_build_object('run',to_jsonb(r),'targets',coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.tenant_id) FROM tenant_retirement.fences f WHERE f.tenant_id=ANY(r.target_ids)),'[]'::jsonb),'events',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM tenant_retirement.events e WHERE e.run_id=r.id),'[]'::jsonb)) INTO result
 FROM tenant_retirement.runs r WHERE r.id=p_run;
 IF result IS NULL THEN RAISE EXCEPTION 'Unknown retirement run'; END IF;
 RETURN result;
END $$;

CREATE FUNCTION tenant_retirement.openbooks_retirement_failure(p_run uuid,p_tenant uuid,p_plan text,p_code text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM tenant_retirement.runs r JOIN tenant_retirement.fences f ON f.run_id=r.id WHERE r.id=p_run AND r.plan_digest=p_plan AND f.tenant_id=p_tenant AND f.state='quarantined') THEN RAISE EXCEPTION 'No matching quarantined retirement target'; END IF;
 INSERT INTO tenant_retirement.events(run_id,tenant_id,kind,login_name,detail) VALUES(p_run,p_tenant,'target_rolled_back',session_user,jsonb_build_object('code',left(p_code,80)));
END $$;

-- Releasing quarantine never recreates a deleted company or edits business data.
CREATE FUNCTION tenant_retirement.openbooks_retirement_release(p_run uuid,p_tenant uuid,p_plan text,p_actor uuid,p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE run tenant_retirement.runs; fence tenant_retirement.fences;
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM tenant_retirement.runs WHERE id=p_run;
 IF NOT FOUND OR run.plan_digest IS DISTINCT FROM p_plan OR NOT p_tenant=ANY(run.target_ids) THEN RAISE EXCEPTION 'Release requires the exact reviewed retirement target'; END IF;
 IF length(coalesce(p_reason,'')) NOT BETWEEN 12 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND org_id=ANY(run.retain_ids) AND is_active) THEN RAISE EXCEPTION 'Release requires a retained active actor and an explicit reason'; END IF;
 SELECT * INTO fence FROM tenant_retirement.fences WHERE tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND OR fence.run_id IS DISTINCT FROM p_run OR fence.state<>'quarantined' OR NOT EXISTS(SELECT 1 FROM public.orgs WHERE id=p_tenant) THEN RAISE EXCEPTION 'Only an existing quarantined target can be released; deleted history requires backup restoration'; END IF;
 UPDATE tenant_retirement.fences SET run_id=NULL,state='active',receipt=NULL,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined';
 IF NOT FOUND THEN RAISE EXCEPTION 'Release did not update its owned fence'; END IF;
 INSERT INTO tenant_retirement.events(run_id,tenant_id,kind,login_name,detail) VALUES(p_run,p_tenant,'quarantine_released',session_user,jsonb_build_object('actorId',p_actor,'reason',p_reason,'before',to_jsonb(fence),'afterState','active'));
END $$;

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA tenant_retirement TO PUBLIC;
